async function compressImageForAI(file,maxSide=1600,quality=.9){
    if(!file.type.startsWith('image/')||file.type.includes('heic')||file.type.includes('heif'))return file;
    try{
        const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'}),scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));
        const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
        const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
        const hasTransparentPixel=()=>{if(file.type!=='image/png')return false;const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;for(let i=3;i<pixels.length;i+=4)if(pixels[i]<255)return true;return false},hasAlpha=hasTransparentPixel();
        const outputType=hasAlpha?'image/png':'image/jpeg',outputQuality=outputType==='image/png'?undefined:quality;
        const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('图片压缩失败')),outputType,outputQuality));
        if(blob.size>=file.size)return file;
        const ext=outputType==='image/png'?'.png':'.jpg',name=(file.name||'pickup').replace(/\.[^.]+$/,'')+ext;
        return new File([blob],name,{type:outputType,lastModified:file.lastModified||Date.now()});
    }catch{return file}
}
function fileSizeText(size){return size>1024*1024?(size/1024/1024).toFixed(1)+'MB':Math.max(1,Math.round(size/1024))+'KB'}
function renderImagePreview(){const box=$('#imagePreview'),grid=box.querySelector('.image-preview-grid');grid.innerHTML='';selectedImageFiles.forEach(file=>{const url=URL.createObjectURL(file),card=document.createElement('div');card.className='image-preview-card';card.innerHTML='<img alt="待识别图片预览"><span>'+esc(fileSizeText(file.size))+'</span>';const img=card.querySelector('img');img.onload=()=>URL.revokeObjectURL(url);img.src=url;grid.appendChild(card)});box.classList.toggle('hidden',selectedImageFiles.length<1)}
$('#imageInput').onchange=e=>{const files=[...(e.target.files||[])].filter(f=>f.type.startsWith('image/'));if(!files.length){$('#imageRecognizeError').textContent='请选择图片文件';return}if(files.length>5){$('#imageRecognizeError').textContent='一次最多选择5张图片';selectedImageFiles=files.slice(0,5)}else{$('#imageRecognizeError').textContent='';selectedImageFiles=files}renderImagePreview()};
$('#imageRecognizeForm').onsubmit=async e=>{e.preventDefault();if(!selectedImageFiles.length){$('#imageRecognizeError').textContent='请先选择照片或相册图片';return}const f=e.currentTarget,b=f.querySelector('button[type="submit"]'),label=b.querySelector('span'),files=[...selectedImageFiles];$('#imageRecognizeError').textContent='';b.disabled=true;b.className='primary-button';let queued=0,errors=[];try{for(let i=0;i<files.length;i++){label.textContent=`正在压缩 ${i+1}/${files.length}`;const uploadFile=await compressImageForAI(files[i]);label.textContent=`正在上传 ${i+1}/${files.length}`;const fd=new FormData();fd.append('image',uploadFile,uploadFile.name||'pickup.jpg');const r=await fetch('/api/image-recognize',{method:'POST',headers:{'X-CSRF-Token':window.PICKUP.csrf},body:fd});let d={};try{d=await r.json()}catch{}const ids=d.data&&Array.isArray(d.data.message_ids)?d.data.message_ids:[],status=d.data&&d.data.status;if(r.status!==202||d.code!==0||!['queued','duplicate','failed_history'].includes(status)||!ids.length){errors.push(`第${i+1}张：${d.message||'上传失败'}`);continue}if(status==='queued')queued+=ids.length;else if(status==='duplicate'){queued+=ids.length;toast('这张图片已识别过，无需重复提交')}else errors.push(`第${i+1}张：${d.message||'历史识别失败，请重试'}`)}if(!queued)throw new Error(errors.join('；')||'图片上传失败');recordsDirty=true;b.classList.add('success');label.textContent='✓ 已提交识别';toast(errors.length?`已提交 ${queued} 条，${errors.length} 张失败`:`已提交 ${queued} 条图片识别`);setTimeout(()=>{closeSheets();resetImageRecognizeSheet();loadAiStatus({silent:true})},2000)}catch(err){$('#imageRecognizeError').textContent=err.message;b.classList.add('error');label.textContent='提交失败';setTimeout(()=>{b.disabled=false;b.className='primary-button';label.textContent='重新提交'},1600)}};

