async function loadAiSettings(){const root=$('#aiSettingsContent');root.innerHTML='<div class="loading-state">正在加载</div>';try{const d=await api('/api/ai/settings'),list=d.data;let official={available:0,selected:0};try{official=(await api('/api/ai/official')).data}catch{official={available:0,selected:0,status_error:true}}root.innerHTML=`${official?.is_enabled===1?officialAiCard(official):''}<div class="settings-toolbar settings-hero"><div><span>AI 引擎</span><strong>识别模型</strong><p>管理你自己的多模态接口和模型</p></div><button id="addProviderButton" class="toolbar-add" aria-label="新增模型"><i class="fa-solid fa-plus"></i><span>添加</span></button></div><div id="aiEditorModal" class="settings-editor-modal hidden" role="dialog" aria-modal="true" aria-labelledby="aiEditorTitle"><form id="aiProviderForm" class="settings-editor-dialog settings-editor"><input type="hidden" name="id"><div class="settings-editor-head"><span class="settings-editor-icon"><i class="fa-solid fa-wand-magic-sparkles"></i></span><div><strong id="aiEditorTitle">添加模型</strong><small>OpenAI 兼容接口</small></div><button type="button" id="closeAiEditor" class="icon-btn settings-editor-close" aria-label="关闭模型编辑"><i class="fa-solid fa-xmark"></i></button></div><div class="settings-field-grid"><label class="settings-field"><span>显示名称</span><input name="display_name" placeholder="例如：豆包 Mini" required></label><label class="settings-field"><span>接口地址</span><input name="base_url" type="url" placeholder="https://api.example.com/v1" required></label></div><label class="settings-field"><span>API Key</span><input name="api_key" type="password" autocomplete="off" placeholder="编辑时留空表示不更换"><small>密钥仅保存在你的个人配置中</small></label><label class="settings-field"><span>模型</span><div class="model-input-row"><input name="model_name" id="modelField" placeholder="填写模型 ID" required><button type="button" class="field-action" id="fetchModels"><i class="fa-solid fa-cloud-arrow-down"></i><span>获取</span></button><button type="button" class="field-action hidden" id="manualModelButton"><i class="fa-solid fa-keyboard"></i><span>手动</span></button></div></label>${official?.is_enabled===1?officialAiCard(official,true):''}<a class="ai-tutorial-card" href="https://q.mcoud.cn/article/2"><i class="fa-solid fa-book-open"></i><span><strong>自己添加模型教程</strong><small>不会配置？点击查看完整教程</small></span><i class="fa-solid fa-chevron-right"></i></a><div id="aiFormError" class="form-error"></div><div class="settings-editor-actions"><button type="button" class="quiet-button" id="cancelProviderEdit">取消</button><button type="button" class="quiet-button test-action" id="testAi"><i class="fa-solid fa-plug"></i><span>测试连接</span></button><button type="submit" class="compact-primary"><span>保存配置</span></button></div></form></div><div class="settings-list-head"><span>已添加</span><small>${list.length} 个配置</small></div><div id="providerList" class="provider-list settings-list">${list.length?list.map(providerCard).join(''):`<div class="settings-empty"><i class="fa-solid fa-robot"></i><strong>还没有模型</strong><span>添加一个支持图片的模型开始识别</span></div>`}</div>`;bindAiForm(list)}catch(e){root.innerHTML=empty(e.message)}}
function officialAiCard(x,compact=false){const available=+x.available===1,selected=+x.selected===1,title=esc(x.display_name||'官方模型'),model=esc(x.model_name||'暂未配置'),abnormal=x.status_error?'官方模型状态获取失败，请使用自己的模型':'官方模型异常，请添加自己的模型';return `<article class="official-ai-card ${compact?'compact':''} ${selected?'selected':''} ${available?'':'abnormal'}"><span class="provider-mark"><i class="fa-solid fa-shield-heart"></i></span><div><strong>${title}</strong><span>${available?`免费使用 · ${model}`:abnormal}</span></div><button type="button" data-use-official ${available&&!selected?'':'disabled'}>${selected?'当前使用':'使用官方模型'}</button></article>`}function providerCard(x){const icon=(label,fa,attr,extra='')=>`<button class="provider-icon-action ${extra}" ${attr} aria-label="${label}" title="${label}"><i class="fa-solid ${fa}"></i><span class="provider-action-label">${label}</span></button>`;return `<article class="provider-card ${+x.is_active?'active':''}"><div class="provider-main"><span class="provider-mark" aria-hidden="true"><i class="fa-solid fa-robot provider-avatar-icon"></i></span><div><div class="provider-title-line"><strong>${esc(x.display_name)}</strong>${+x.is_active?'<span class="provider-status"><i class="fa-solid fa-circle-check"></i>使用中</span>':''}</div><span class="provider-model">${esc(x.model_name)}</span><small>${esc(x.base_url)}</small></div></div><div class="provider-actions">${+x.is_active?'':icon('启用','fa-check',`data-select-provider="${x.id}"`)}${icon('编辑','fa-pen',`data-edit-provider="${x.id}"`)}${icon('测试','fa-plug',`data-test-provider="${x.id}"`)}${+x.is_active?'':icon('删除','fa-trash',`data-delete-provider="${x.id}"`,'danger')}</div></article>`}
