async function loadApi(){try{const d=await api('/api/tokens'),x=d.data,getUrl=`${x.url}&text=${encodeURIComponent('短信内容')}&phone=${encodeURIComponent('发件号码')}`,baseUrl=x.url.split('?')[0];$('#apiContent').innerHTML=`<div class="api-card"><h3>你的专属 API URL</h3><div class="api-url" id="apiUrl">${esc(x.url)}</div><div class="copy-row"><button class="secondary-button" data-copy="url"><i class="fa-regular fa-copy"></i> 复制 URL</button><button class="secondary-button danger-soft" id="regenToken">重新生成</button></div><div class="parcel-meta">最近连接：${esc(x.last_used_at||'尚未连接')}</div></div><h4>方式一：POST JSON（推荐）</h4><ol class="steps"><li>iPhone“自动化”选择“收到信息”。</li><li>添加“获取 URL 内容”，粘贴上方专属 URL。</li><li>方法选 <strong>POST</strong>，请求体选 <strong>JSON</strong>，请求头留空。</li><li><strong>txt</strong> 对应短信正文，<strong>phone</strong> 对应发件人。</li></ol><div class="code-block">POST ${esc(x.url)}\nContent-Type: application/json\n\n{\n  "txt": "短信内容",\n  "phone": "发件号码"\n}</div><h4>方式二：GET URL 参数</h4><p class="api-note">方法选择 GET，把短信正文放到 <strong>text</strong> 或 <strong>txt</strong> 参数；发件号码放到 <strong>phone</strong>。参数必须进行 URL 编码。</p><div class="code-block">GET ${esc(getUrl)}</div><h4>方式三：GET 请求头 txt</h4><p class="api-note">方法选择 GET，URL 使用专属 URL；在请求头中添加 <strong>txt</strong>，值为短信正文。发件号码可放 URL 的 phone 参数。</p><div class="code-block">GET ${esc(x.url)}&phone=发件号码\ntxt: 短信内容</div><h4>方式四：POST 纯文本</h4><p class="api-note">请求体直接发送短信正文。此方式无法在纯文本正文里同时提供 phone，推荐优先使用 JSON。</p><div class="code-block">POST ${esc(x.url)}\nContent-Type: text/plain\n\n短信内容</div><h4>方式五：Bearer Token + JSON</h4><p class="api-note">适用于其他程序或服务器。URL 不带 k，把 Token 放在 Authorization 请求头。</p><div class="code-block">POST ${esc(baseUrl)}\nAuthorization: Bearer ${esc(x.token)}\nContent-Type: application/json\n\n{\n  "txt": "短信内容",\n  "phone": "发件号码"\n}</div><h4>兼容字段</h4><ul class="steps"><li>短信正文支持：<strong>txt、text、message、sms、content</strong>。</li><li>发件号码支持：<strong>phone、sender、from</strong>。</li><li>接口同时支持 GET 和 POST；推荐使用 POST JSON，内容最完整。</li></ul><h4>返回结果</h4><div class="code-block">{\n  "code": 0,\n  "status": "created",\n  "message": "识别并保存成功",\n  "data": {\n    "station": "驿站名称",\n    "codes": ["8-3-376"]\n  }\n}</div><ul class="steps"><li><strong>created</strong>：识别并保存成功。</li><li><strong>duplicate</strong>：相同短信已接收，不重复添加。</li><li><strong>unauthorized</strong>：API 地址或 Token 错误。</li></ul>`;$('[data-copy="url"]').onclick=()=>navigator.clipboard.writeText(x.url).then(()=>toast('URL 已复制'));$('#regenToken').onclick=()=>confirmBox('重新生成 API 连接？','旧地址会立即失效，需要同步修改 iPhone 快捷指令。',async()=>{await api('/api/tokens',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'regenerate'})});toast('已重新生成');loadApi()})}catch(e){$('#apiContent').innerHTML=empty(e.message)}}
