let notificationConfig=null;function notificationCapabilities(){return{ios:isIosDevice(),standalone:isStandaloneApp(),secure:isSecureContext,notification:'Notification'in window,serviceWorker:'serviceWorker'in navigator,pushManager:'PushManager'in window,permission:'Notification'in window?Notification.permission:'unsupported'}}function renderNotificationDiagnostic(extra=''){const c=notificationCapabilities(),d=$('#notificationDiagnostic');if(d)d.textContent=`环境：${c.standalone?'主屏幕App':'浏览器'} · 权限：${c.permission} · Push：${c.pushManager?'支持':'不支持'}${extra?' · '+extra:''}`;return c}function urlBase64ToUint8Array(value){const padding='='.repeat((4-value.length%4)%4),base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64);return Uint8Array.from([...raw].map(x=>x.charCodeAt(0)))}async function notificationRegistration(){let registration=await navigator.serviceWorker.getRegistration('/');if(!registration)registration=await navigator.serviceWorker.register('/service-worker.js',{scope:'/'});await registration.update();if(!registration.active)registration=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('Service Worker 启动超时')),8000))]);return registration}async function saveDeviceSubscription(registration){if(!notificationConfig)notificationConfig=(await api('/api/notifications')).data;let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(notificationConfig.vapid_public_key)});await api('/api/notifications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'subscribe',subscription:subscription.toJSON()})});return subscription}async function loadNotificationSettings(){const sheet=$('#subscriptionSheet'),hint=$('#notificationHint'),status=$('#notificationDeviceStatus'),notificationDeviceToggle=$('#deviceNotificationEnabled');sheet.classList.add('notification-sheet-loading');status.textContent='正在加载设置';try{notificationConfig=(await api('/api/notifications')).data;const pref=notificationConfig.preferences||{};document.querySelector('[name="new_pending_enabled"]').checked=!!pref.new_pending_enabled;document.querySelector('[name="daily_enabled"]').checked=!!pref.daily_enabled;document.querySelector('[name="daily_time"]').value=pref.daily_time||'20:00';if(isNativeAndroidApp()){notificationDeviceToggle.checked=false;notificationDeviceToggle.disabled=true;status.textContent='原生 App 推送尚未接入';hint.textContent='提醒偏好仍会保存；本设备 Web Push 不可用，后续由原生推送接管。';renderNotificationDiagnostic('等待原生推送供应商');return}const registration='serviceWorker'in navigator?await navigator.serviceWorker.getRegistration('/'):null,subscription=registration?.pushManager?await registration.pushManager.getSubscription():null;notificationDeviceToggle.checked=!!subscription;notificationDeviceToggle.disabled=false;status.textContent=subscription?'本设备已订阅':'本设备未订阅';renderNotificationDiagnostic();if(Notification.permission==='denied')hint.textContent='通知权限已关闭，请前往“设置 → 通知 → 取件助手”重新允许。'}catch(error){status.textContent='加载失败';hint.textContent=error?.message||'订阅状态加载失败';throw error}finally{sheet.classList.remove('notification-sheet-loading')}}async function openNotificationSettings(){const sheet=$('#subscriptionSheet');openSheet('#subscriptionSheet');await loadNotificationSettings().catch(error=>toast(error?.message||'订阅设置加载失败'))}$('[data-open="subscription"]').onclick=openNotificationSettings;$('#testNotificationButton').onclick=async()=>{const b=$('#testNotificationButton'),hint=$('#notificationHint');let stage='环境检查';b.disabled=true;b.className='primary-button notification-test-button';b.querySelector('span').textContent='正在测试…';try{const c=renderNotificationDiagnostic('检查中');if(!c.secure||!c.notification||!c.serviceWorker||!c.pushManager)throw new Error('当前环境缺少网页推送能力');if(c.ios&&!c.standalone)throw new Error('请从主屏幕上的取件助手打开');stage='请求权限';let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('请在系统提示中选择“允许”');stage='准备Service Worker';const registration=await notificationRegistration();stage='登记本设备';await saveDeviceSubscription(registration);stage='服务器发送测试';const sent=await api('/api/notifications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'test_push'})});$('#deviceNotificationEnabled').checked=true;$('#notificationDeviceStatus').textContent='本设备已订阅';b.classList.add('success');b.querySelector('span').textContent='✓ 服务器推送已发送';hint.textContent=`服务器已向 ${sent.data.sent} 台设备发送，请查看系统通知。`;renderNotificationDiagnostic('服务器投递成功');setTimeout(()=>{b.disabled=false;b.className='primary-button notification-test-button';b.querySelector('span').textContent='再次测试服务器推送'},2000)}catch(error){b.classList.add('error');b.querySelector('span').textContent='✗ 测试失败';hint.textContent=`${stage}失败：${error?.message||error}`;renderNotificationDiagnostic(`${stage} / ${error?.name||'Error'}`);setTimeout(()=>{b.disabled=false;b.className='primary-button notification-test-button';b.querySelector('span').textContent='重新测试并允许'},2400)}};$('#deviceNotificationEnabled').onchange=async e=>{const input=e.currentTarget,status=$('#notificationDeviceStatus');input.disabled=true;try{if(input.checked){const c=notificationCapabilities();if(c.ios&&!c.standalone)throw new Error('请从主屏幕App中开启');let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('通知权限未允许');await saveDeviceSubscription(await notificationRegistration());status.textContent='本设备已订阅';toast('本设备通知已开启')}else{const registration=await navigator.serviceWorker.getRegistration('/'),subscription=await registration?.pushManager?.getSubscription();if(subscription){await api('/api/notifications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'unsubscribe',endpoint:subscription.endpoint})});await subscription.unsubscribe()}status.textContent='本设备未订阅';toast('本设备通知已关闭')}}catch(error){input.checked=!input.checked;toast(error?.message||'操作失败','error')}finally{input.disabled=false;renderNotificationDiagnostic()}};let notificationSaveInFlight=false;$('#saveNotificationSettings').onclick=async()=>{if(notificationSaveInFlight)return;const b=$('#saveNotificationSettings'),time=document.querySelector('[name="daily_time"]');notificationSaveInFlight=true;b.disabled=true;b.className='primary-button';b.querySelector('span').textContent='正在保存…';try{const data={action:'save_preferences',new_pending_enabled:document.querySelector('[name="new_pending_enabled"]').checked,daily_enabled:document.querySelector('[name="daily_enabled"]').checked,daily_time:time.value};const result=await api('/api/notifications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});notificationConfig={...(notificationConfig||{}),preferences:{...(notificationConfig?.preferences||{}),...result.data}};time.value=result.data.daily_time;b.classList.add('success');b.querySelector('span').textContent='保存成功';setTimeout(()=>{b.disabled=false;b.className='primary-button';b.querySelector('span').textContent='保存订阅设置'},1200)}catch(error){b.classList.add('error');b.querySelector('span').textContent='✗ 保存失败';setTimeout(()=>{b.disabled=false;b.className='primary-button';b.querySelector('span').textContent='重新保存'},1600)}finally{notificationSaveInFlight=false}};
function syncVisibleData(){if(document.visibilityState!=='visible'||document.querySelector('.sheet:not(.hidden),.modal-wrap:not(.hidden)'))return;loadAiStatus({silent:true});const tab=document.querySelector('.nav-item.active')?.dataset.tab;if(tab==='home')loadHome({incremental:true});else if(tab==='records')loadRecords($('.filter.active').dataset.status,$('.period-filter.active').dataset.period,{incremental:true,force:true})}setInterval(syncVisibleData,10000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncVisibleData()});function clearAppShellCache(){navigator.serviceWorker?.controller?.postMessage({type:'CLEAR_APP_SHELL'})}$('#articleHistoryButton').onclick=()=>location.href='/articles';
$('#logoutButton').onclick=()=>confirmBox('退出当前设备？','其他设备不会退出。',async()=>{localStorage.removeItem(homeSnapshotKey());clearAppShellCache();await api('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});location.href='/login'});hydrateHomeSnapshot();openPushAfterHomeReady().catch(()=>{history.replaceState(null,'','/');toast('通知内容暂时无法打开')});if(!launchTarget)loadHome({incremental:homeItems.length>0}).catch(()=>{});

function showUpdateModal(serverVersion,{force=false}={}){if(!force&&localStorage.getItem('pickup:update-prompted-version')===serverVersion)return;if(!force)localStorage.setItem('pickup:update-prompted-version',serverVersion);let modal=document.getElementById('updateModal');if(!modal){modal=document.createElement('div');modal.id='updateModal';modal.className='modal-wrap';modal.innerHTML='<div class="modal update-modal"><div class="modal-icon"><i class="fa-solid fa-arrow-rotate-right"></i></div><h3>发现新版本</h3><p>新版本已经准备好，立即更新可获得最新功能和细节优化。</p><div class="modal-actions"><button id="laterUpdateButton">稍后</button><button id="doUpdateButton" class="confirm-action">立即更新</button></div></div>';document.body.appendChild(modal)}else modal.classList.remove('hidden');document.getElementById('laterUpdateButton').onclick=()=>{sessionStorage.setItem('pickup:update-dismissed',serverVersion);modal.classList.add('hidden')};document.getElementById('doUpdateButton').onclick=()=>performAppUpdate(serverVersion)}
async function performAppUpdate(serverVersion){const b=document.getElementById('doUpdateButton');if(!b)return;b.disabled=true;b.textContent='更新中…';try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('pickup-static-')).map(k=>caches.delete(k)))}Object.keys(localStorage).filter(key=>key.startsWith('pickup:')).forEach(key=>localStorage.removeItem(key));sessionStorage.clear();let refreshing=false;navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.replace('/?v='+encodeURIComponent(serverVersion)+'&t='+Date.now())});const reg=await navigator.serviceWorker?.getRegistration('/');if(reg){await reg.update();const worker=reg.waiting||reg.installing||reg.active;if(worker)worker.postMessage({type:'SKIP_WAITING'})}setTimeout(()=>location.replace('/?v='+encodeURIComponent(serverVersion)+'&t='+Date.now()),900)}catch(e){b.classList.add('error');b.textContent='更新失败';setTimeout(()=>{b.disabled=false;b.classList.remove('error');b.textContent='重新更新'},2000)}}
async function checkAboutUpdate({auto=false}={}){const b=$('#checkUpdateButton'),label=b.querySelector('span'),status=$('#aboutUpdateStatus');b.disabled=true;b.className='primary-button about-update-button';label.textContent='正在检查…';status.textContent='正在获取最新版本信息';try{const r=await fetch('/api/version?t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d||d.code!==0||!d.version)throw new Error('版本信息获取失败');const current=window.PICKUP.appVersion||'未知';$('#aboutVersion').textContent=current;if(d.version===current){b.classList.add('success');label.textContent='已是最新版本';status.textContent=`当前已是最新版本 ${current}`}else{b.disabled=false;label.textContent='发现新版本，立即更新';status.textContent=`最新版本 ${d.version}`;b.onclick=()=>showUpdateModal(d.version,{force:true});return}}catch(e){b.classList.add('error');label.textContent='检查失败';status.textContent=e.message||'检查更新失败'}setTimeout(()=>{b.disabled=false;b.className='primary-button about-update-button';label.textContent='重新检查';b.onclick=checkAboutUpdate},1800)}
$('#checkUpdateButton').onclick=checkAboutUpdate;
async function checkAppVersion(){try{const r=await fetch('/api/version?t='+Date.now(),{cache:'no-store'}),d=await r.json();if(d&&d.code===0&&d.version&&window.PICKUP.appVersion&&d.version!==window.PICKUP.appVersion)showUpdateModal(d.version)}catch{}}
setTimeout(checkAppVersion,1200);

